#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
"""Convert Project Wycheproof JSON test vectors into C++ include files.

Usage: gen_vectors.py <dir with wycheproof json> <output dir>

The generated files under tests/vectors/ are derived from
https://github.com/C2SP/wycheproof (Apache-2.0) and are committed so that the
build needs no network access for test data.
"""
import json
import sys
from pathlib import Path

HEADER = """// Generated by tools/gen_vectors.py from Project Wycheproof ({src}).
// Source: https://github.com/C2SP/wycheproof  License: Apache-2.0
// Do not edit by hand.
"""

RESULT = {"valid": "'v'", "invalid": "'i'", "acceptable": "'a'"}


def q(s):
    return '"' + s + '"'


def load(src_dir, name):
    with open(Path(src_dir) / name, encoding="utf-8") as f:
        return json.load(f)


def ecdsa(src_dir, out_dir):
    name = "ecdsa_secp256r1_sha256_p1363_test.json"
    data = load(src_dir, name)
    rows = []
    for g in data["testGroups"]:
        pub = g["publicKey"]["uncompressed"]
        assert g["sha"] == "SHA-256" and len(pub) == 130
        for t in g["tests"]:
            rows.append("{%d, %s, %s, %s, %s}," % (
                t["tcId"], q(pub), q(t["msg"]), q(t["sig"]), RESULT[t["result"]]))
    (Path(out_dir) / "wycheproof_ecdsa_p256.inc").write_text(
        HEADER.format(src=name) + "\n".join(rows) + "\n", encoding="utf-8", newline="\n")
    return len(rows)


def ecdh(src_dir, out_dir):
    name = "ecdh_secp256r1_ecpoint_test.json"
    data = load(src_dir, name)
    rows = []
    for g in data["testGroups"]:
        for t in g["tests"]:
            rows.append("{%d, %s, %s, %s, %s}," % (
                t["tcId"], q(t["public"]), q(t["private"]), q(t["shared"]),
                RESULT[t["result"]]))
    (Path(out_dir) / "wycheproof_ecdh_p256.inc").write_text(
        HEADER.format(src=name) + "\n".join(rows) + "\n", encoding="utf-8", newline="\n")
    return len(rows)


def hkdf(src_dir, out_dir):
    name = "hkdf_sha256_test.json"
    data = load(src_dir, name)
    rows = []
    for g in data["testGroups"]:
        for t in g["tests"]:
            rows.append("{%d, %s, %s, %s, %d, %s, %s}," % (
                t["tcId"], q(t["ikm"]), q(t["salt"]), q(t["info"]), t["size"],
                q(t["okm"]), RESULT[t["result"]]))
    (Path(out_dir) / "wycheproof_hkdf_sha256.inc").write_text(
        HEADER.format(src=name) + "\n".join(rows) + "\n", encoding="utf-8", newline="\n")
    return len(rows)


def aes_gcm(src_dir, out_dir):
    name = "aes_gcm_test.json"
    data = load(src_dir, name)
    rows = []
    for g in data["testGroups"]:
        # The bootloader only ever uses AES-256-GCM with 96-bit nonces and
        # full 128-bit tags; other parameter sets are out of scope.
        if g["keySize"] != 256 or g["ivSize"] != 96 or g["tagSize"] != 128:
            continue
        for t in g["tests"]:
            rows.append("{%d, %s, %s, %s, %s, %s, %s, %s}," % (
                t["tcId"], q(t["key"]), q(t["iv"]), q(t["aad"]), q(t["msg"]),
                q(t["ct"]), q(t["tag"]), RESULT[t["result"]]))
    (Path(out_dir) / "wycheproof_aes256_gcm.inc").write_text(
        HEADER.format(src=name) + "\n".join(rows) + "\n", encoding="utf-8", newline="\n")
    return len(rows)


def main():
    if len(sys.argv) != 3:
        sys.exit(__doc__)
    src_dir, out_dir = sys.argv[1], sys.argv[2]
    Path(out_dir).mkdir(parents=True, exist_ok=True)
    for fn in (ecdsa, ecdh, hkdf, aes_gcm):
        print("%-8s %d vectors" % (fn.__name__, fn(src_dir, out_dir)))


if __name__ == "__main__":
    main()
